def transform(g):
    g=[r[:] for r in g]; h,w=len(g),len(g[0])
    bg=max(set(x for r in g for x in r), key=lambda c: sum(r.count(c) for r in g))
    cells=[(i,j,g[i][j]) for i in range(h) for j in range(w) if g[i][j]!=bg]
    s={(a,b) for a,b,_ in cells}
    block=None
    for i in range(h):
        for j in range(w):
            if all((i+di,j+dj) in s for di in (0,1) for dj in (0,1)):
                block=(i,j); break
        if block: break
    bi,bj=block
    corners=[(bi,bj),(bi+1,bj),(bi,bj+1),(bi+1,bj+1)]
    for ci,cj in corners:
        for di in (-1,0,1):
            for dj in (-1,0,1):
                if (di,dj)!=(0,0) and (ci+di,cj+dj) in s and (ci+di,cj+dj) not in [(a,b) for a,b in corners]:
                    sc=g[ci+di][cj+dj]
                    i,j=ci+2*di,cj+2*dj
                    while 0<=i<h and 0<=j<w:
                        g[i][j]=sc; i+=di; j+=dj
    return g
